public class Virus {
    private static final String virusName = "新冠病毒";
    private static final int virusCount = 5;

    public static void main(String[] args) {
        // Create an array of five strings with the virus name
        String[] virusNames = new String[virusCount];
        for (int i = 0; i < virusCount; i++) {
            virusNames[i] = virusName;
        }

        // Print each string in the array
        IntStream virusNamesStream = IntStream.of(virusNames);
        System.out.println("病毒名称: " + virusNamesStream);
    }
}
